@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Notion DNA — paper white, ink gray, serif calm, tool that disappears */
.theme-notion-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0.004 91.4);
  --surface-2: oklch(0.949 0.005 95.1);
  --fg: oklch(0.313 0.008 80);
  --fg-muted: oklch(0.569 0.005 91.5);
  --accent: oklch(0.606 0.167 252.7);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.659 0.159 55.7);
  --line: oklch(0.933 0.003 106.5);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.645 0.185 25.9);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Inter", -apple-system, sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.03em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-notion-dna h1,
.theme-notion-dna h2,
.theme-notion-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-notion-dna h1 { font-weight: 600; }
.theme-notion-dna button { font-weight: 500; }
.theme-notion-dna a { text-decoration: underline; text-decoration-color: var(--line); text-underline-offset: 3px; }
.theme-notion-dna ::selection { background: oklch(0.85 0.06 240 / 60%); }

/* depth */
.theme-notion-dna table { border-collapse: collapse; }
.theme-notion-dna th, .theme-notion-dna td { border: 1px solid var(--line); }
.theme-notion-dna thead th { background: var(--surface); color: var(--fg-muted); font-weight: 500; font-size: 0.8125rem; }
.theme-notion-dna tbody tr:hover { background: color-mix(in oklab, var(--surface) 70%, transparent); }
.theme-notion-dna input, .theme-notion-dna select, .theme-notion-dna textarea { background: var(--bg); border: 1px solid var(--line); transition: border-color 100ms ease, box-shadow 100ms ease; }
.theme-notion-dna input:focus-visible, .theme-notion-dna select:focus-visible, .theme-notion-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in oklab, var(--accent) 25%, transparent); }
.theme-notion-dna kbd { font-size: 0.75em; background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 3px; padding: 0.1em 0.4em; color: var(--fg-muted); }
.theme-notion-dna a:hover { background: var(--surface-2); }
.theme-notion-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-notion-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-notion-dna ::-webkit-scrollbar-thumb { background: oklch(0.85 0.005 95); border-radius: var(--radius-pill); }
.theme-notion-dna ::-webkit-scrollbar-thumb:hover { background: oklch(0.75 0.005 95); }
.theme-notion-dna .label-caps { font-size: 0.6875rem; color: var(--fg-muted); letter-spacing: 0.04em; }
.theme-notion-dna .themed-border { border-color: var(--line); }
.theme-notion-dna button { transition: background 100ms ease; }
.theme-notion-dna button:active { background: var(--surface-2); }
.theme-notion-dna hr { border-color: var(--line); }

/* fidelity: the Notion APP, not the marketing site */
.theme-notion-dna h1 { font-weight: 700; letter-spacing: -0.015em; }
.theme-notion-dna h2, .theme-notion-dna h3 { font-weight: 600; }
.theme-notion-dna button { font-weight: 500; box-shadow: none; }
/* quiet chrome: active nav + sidebar CTA are gray/bordered, never filled blue */
.theme-notion-dna nav span.bg-accent { background: oklch(0.93 0.004 90); color: oklch(0.313 0.008 80); }
.theme-notion-dna nav span.bg-accent .size-4 { color: oklch(0.45 0.01 80); }
.theme-notion-dna aside button.bg-accent, .theme-notion-dna aside .bg-accent[class*="justify-center"] { background: #ffffff; color: oklch(0.313 0.008 80); border: 1px solid oklch(0.91 0.004 90); }
/* pastel property chips with dark text — the Notion tag palette */
.theme-notion-dna span.bg-accent.rounded-theme-pill { background: #d3e5ef; color: #183347; border-color: transparent; }
.theme-notion-dna.theme-notion-dna span.bg-danger { background: #ffe2dd; color: #5d1715; border-color: transparent; }
.theme-notion-dna.theme-notion-dna span.bg-warning { background: #fdecc8; color: #402c1b; border-color: transparent; }
.theme-notion-dna.theme-notion-dna span.bg-success { background: #dbeddb; color: #1c3829; border-color: transparent; }
.theme-notion-dna span.bg-surface-2.rounded-theme-pill { background: #f1f0ef; color: #37352f; border-color: transparent; }
/* database-table feel: hairlines, quiet headers, gray hover */
.theme-notion-dna th { color: oklch(0.55 0.01 80); font-weight: 500; font-size: 12px; border-bottom: 1px solid #e9e9e7; }
.theme-notion-dna td { border-bottom: 1px solid #efefee; }
.theme-notion-dna tbody tr:hover { background: #f1f0ef; }
.theme-notion-dna input, .theme-notion-dna textarea { background: #f7f6f3; border-color: #e9e9e7; }
.theme-notion-dna input:focus, .theme-notion-dna textarea:focus { background: #ffffff; border-color: #2383e2; box-shadow: 0 0 0 2px rgba(35, 131, 226, 0.2); }
.theme-notion-dna ::selection { background: rgba(35, 131, 226, 0.22); }
.theme-notion-dna ::-webkit-scrollbar { width: 10px; }
.theme-notion-dna ::-webkit-scrollbar-thumb { background: #d3d1cb; border-radius: 5px; }

/* alt mode: Notion's real dark — the famous #191919 */
.theme-notion-dna.alt-mode {
  --bg: oklch(0.235 0.002 80);
  --surface: oklch(0.265 0.002 80);
  --surface-2: oklch(0.3 0.003 80);
  --fg: oklch(0.87 0.004 80);
  --fg-muted: oklch(0.62 0.006 80);
  --line: oklch(1 0 0 / 9%);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 35%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 45%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 55%);
}
.theme-notion-dna.alt-mode nav span.bg-accent { background: oklch(0.33 0.003 80); color: oklch(0.87 0.004 80); }
.theme-notion-dna.alt-mode aside button.bg-accent { background: oklch(0.3 0.003 80); color: oklch(0.87 0.004 80); border-color: oklch(1 0 0 / 12%); }
.theme-notion-dna.alt-mode span.bg-accent.rounded-theme-pill { background: #28456c; color: #cbdcf0; }
.theme-notion-dna.alt-mode span.bg-danger { background: #522e2a; color: #f3c9c4; }
.theme-notion-dna.alt-mode span.bg-warning { background: #4f3b23; color: #f0dcbf; }
.theme-notion-dna.alt-mode span.bg-success { background: #2b4432; color: #c8e0cc; }
.theme-notion-dna.alt-mode th { border-bottom-color: oklch(1 0 0 / 10%); }
.theme-notion-dna.alt-mode td { border-bottom-color: oklch(1 0 0 / 7%); }
.theme-notion-dna.alt-mode tbody tr:hover { background: oklch(0.29 0.003 80); }
.theme-notion-dna.alt-mode input, .theme-notion-dna.alt-mode textarea { background: oklch(0.28 0.003 80); border-color: oklch(1 0 0 / 12%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
